class Solution {
public:
    int maximumSum(vector<int>& nums) {
        const int NEG = -1000000000;
        int dp[4][3];
        for (int i = 0; i <= 3; ++i)
            for (int r = 0; r < 3; ++r) dp[i][r] = NEG;
        dp[0][0] = 0;
        for (int x : nums) {
            for (int k = 3; k >= 1; --k) {
                for (int r = 0; r < 3; ++r) {
                    if (dp[k - 1][r] != NEG)
                        dp[k][(r + x) % 3] = max(dp[k][(r + x) % 3], dp[k - 1][r] + x);
                }
            }
        }
        return max(0, dp[3][0]);
    }
};
